53	/**
54	 * 创建 agent。
55	 *
56	 * config 为 NULL 时使用默认配置。
57	 * runtime 中 NULL 回调先由平台 runtime 补齐，再由 fill_defaults 兜底。
58	 * 已设置的应用回调不会被平台 runtime 覆盖。
59	 * 如果 config.runtime.mutex_create 已设置，会自动创建互斥量。
60	 */
61	agent_t *agent_create(const agent_config_t *config)
62	{
63	    agent_config_t local_config;
64	    agent_runtime_t runtime;
65	    agent_t *agent;
66	
67	    if (config) {
68	        local_config = *config;
69	        agent_runtime_fill_platform(&local_config.runtime);
70	        agent_runtime_fill_defaults(&local_config.runtime);
71	    } else {
72	        local_config = agent_config_default();
73	    }
74	
75	    runtime = local_config.runtime;
76	    agent = (agent_t *)agent_runtime_malloc(&runtime, sizeof(*agent));
77	    if (!agent) {
78	        return NULL;
79	    }
80	
81	    memset(agent, 0, sizeof(*agent));
82	    agent->config = local_config;
83	    agent->runtime = runtime;
84	    agent->limits = local_config.limits.max_steps ? local_config.limits : default_limits();
85	    agent->tool_schema_dirty = true;
86	
87	    if (agent->runtime.mutex_create) {
88	        agent->mutex = agent->runtime.mutex_create(agent->runtime.user_data);
89	    }
90	
91	    return agent;
92	}
