109	/**
110	 * 销毁 agent。
111	 *
112	 * 释放互斥量和 agent 自身。
113	 * 如果 model 通过 agent_set_model_owned() 绑定，同时销毁 model。
114	 * 否则 model 生命周期由应用层管理。
115	 */
116	void agent_destroy(agent_t *agent)
117	{
118	    agent_runtime_t runtime;
119	
120	    if (!agent) {
121	        return;
122	    }
123	
124	    if (agent->model_owned && agent->model) {
125	        agent_model_destroy(agent->model);
126	        agent->model = NULL;
127	        agent->model_owned = false;
128	    }
129	
130	    runtime = agent->runtime;
131	    if (agent->mutex && runtime.mutex_destroy) {
132	        runtime.mutex_destroy(agent->mutex, runtime.user_data);
133	    }
134	    agent_runtime_free(&runtime, agent);
135	}
