137	/**
138	 * 同步推理入口。
139	 *
140	 * 流程：
141	 *   1. 参数校验
142	 *   2. mutex lock → busy 检查 → 设置 busy
143	 *   3. 保存/覆盖 limits，计算 deadline
144	 *   4. emit RUN_START
145	 *   5. agent_loop_run() 执行 ReAct 循环
146	 *   6. 更新 stats，emit RUN_DONE
147	 *   7. 恢复 limits，清除 busy，mutex unlock
148	 */
149	int agent_run(agent_t *agent,
150	              const agent_request_t *request,
151	              agent_response_t *response)
152	{
153	    agent_limits_t saved_limits;
154	    uint64_t start_ms;
155	    uint64_t end_ms;
156	    int ret;
157	
158	    if (!agent || !request || !request->input || !response) {
159	        return AGENT_ERROR_INVALID;
160	    }
161	
162	    /* 尝试加锁，失败说明另一线程持有 */
163	    if (agent_runtime_mutex_lock(&agent->runtime, agent->mutex, 0u) != AGENT_OK) {
164	        return AGENT_ERROR_BUSY;
165	    }
166	
167	    if (agent->busy) {
168	        agent_runtime_mutex_unlock(&agent->runtime, agent->mutex);
169	        return AGENT_ERROR_BUSY;
170	    }
171	
172	    agent->busy = true;
173	
174	    /* 保存当前 limits，允许 request 临时覆盖 */
175	    saved_limits = agent->limits;
176	    if (request->limits) {
177	        agent->limits = *request->limits;
178	    }
179	
180	    response->status = AGENT_ERROR;
181	    response->stats = agent->stats;
182	    if (response->output && response->output_size > 0u) {
183	        response->output[0] = '\0';
184	    }
185	
186	    /* 重置取消标志，计算本次请求 deadline */
187	    agent->cancel_requested = false;
188	    agent->current_run_tool_calls = 0u;
189	    start_ms = agent_runtime_now_ms(&agent->runtime);
190	    agent->run_start_ms = start_ms;
191	    agent->run_deadline_ms = agent->limits.timeout_ms ? start_ms + agent->limits.timeout_ms : 0u;
192	    agent->stats.runs++;
193	
194	    agent_event_emit(agent, AGENT_EVENT_RUN_START, request, 0u, AGENT_OK, "start", NULL, NULL);
195	    ret = agent_loop_run(agent, request, response);
196	
197	    end_ms = agent_runtime_now_ms(&agent->runtime);
198	    agent->stats.last_run_elapsed_ms = end_ms >= start_ms ? end_ms - start_ms : 0u;
199	
200	    /* 根据结果更新统计和 emit 事件 */
201	    if (ret == AGENT_OK) {
202	        agent->stats.completed_runs++;
203	    } else {
204	        agent->stats.failed_runs++;
205	        if (ret == AGENT_ERROR_CANCELLED) {
206	            agent->stats.cancelled_runs++;
207	            agent_event_emit(agent, AGENT_EVENT_CANCELLED, request, 0u, ret, "cancelled", NULL, NULL);
208	        } else if (ret == AGENT_ERROR_TIMEOUT) {
209	            agent->stats.timeout_runs++;
210	            agent_event_emit(agent, AGENT_EVENT_TIMEOUT, request, 0u, ret, "timeout", NULL, NULL);
211	        } else {
212	            agent_event_emit(agent, AGENT_EVENT_ERROR, request, 0u, ret, "agent_run failed", NULL, NULL);
213	        }
214	    }
215	
216	    response->status = ret;
217	    response->stats = agent->stats;
218	    agent_event_emit(agent, AGENT_EVENT_RUN_DONE, request, 0u, ret, "done", NULL, NULL);
219	
220	    /* 恢复 limits，清理运行状态 */
221	    agent->limits = saved_limits;
222	    agent->run_deadline_ms = 0u;
223	    agent->busy = false;
224	    agent_runtime_mutex_unlock(&agent->runtime, agent->mutex);
225	
226	    return ret;
227	}
