229	/**
230	 * 协作式取消。
231	 *
232	 * 通过 critical section 安全设置 cancel_requested（ISR 安全）。
233	 * 如果 model 支持 cancel，同时通知 provider。
234	 * 实际取消发生在 loop 的下一个检查点。
235	 */
236	int agent_cancel(agent_t *agent)
237	{
238	    uint32_t state;
239	
240	    if (!agent) {
241	        return AGENT_ERROR_INVALID;
242	    }
243	
244	    state = agent_runtime_enter_critical(&agent->runtime);
245	    agent->cancel_requested = true;
246	    agent_runtime_exit_critical(&agent->runtime, state);
247	
248	    agent_model_cancel(agent->model);
249	
250	    return AGENT_OK;
251	}
252	
253	/**
254	 * 重置 agent 状态。
255	 *
256	 * 清除 stats、cancel flag、deadline、sessions。
257	 * 不清除已注册的 tools/skills/model/runtime。
258	 */
259	int agent_reset(agent_t *agent)
260	{
261	    if (!agent) {
262	        return AGENT_ERROR_INVALID;
263	    }
264	    if (agent->busy) {
265	        return AGENT_ERROR_BUSY;
266	    }
267	
268	    memset(&agent->stats, 0, sizeof(agent->stats));
269	    agent->cancel_requested = false;
270	    agent->run_start_ms = 0u;
271	    agent->run_deadline_ms = 0u;
272	
273	    /* 清理所有 session 消息，但保留 session 槽位 */
274	    agent_session_clear_all(agent);
275	
276	    return AGENT_OK;
277	}
