int agent_tool_enumerate(const agent_t *agent,
                         agent_tool_enumerate_fn callback,
                         void *user_data)
{
    uint32_t i;

    if (!agent || !callback) {
        return AGENT_ERROR_INVALID;
    }

    for (i = 0u; i < agent->tool_count; i++) {
        const agent_tool_entry_t *entry = &agent->tools[i];
        agent_tool_info_t info;
        int ret;

