        info.flags = entry->def.flags;
        info.timeout_ms = entry->def.timeout_ms;
        info.enabled = agent_tool_entry_is_enabled(entry) ? 1 : 0;
        info.llm_visible = agent_tool_entry_is_llm_visible(entry) ? 1 : 0;

        ret = callback(&info, user_data);
        if (ret != AGENT_OK) {
            return ret;
        }
    }

